import{_ as a,c as e,a2 as r,o as i}from"./chunks/framework.CO0qOYmW.js";const b=JSON.parse('{"title":"RAG 应用工程概述","description":"","frontmatter":{},"headers":[],"relativePath":"ai/05-rag-engineering/01-basics/01-overview.md","filePath":"ai/05-rag-engineering/01-basics/01-overview.md","lastUpdated":1783608971000}'),o={name:"ai/05-rag-engineering/01-basics/01-overview.md"};function d(n,t,l,s,h,c){return i(),e("div",null,t[0]||(t[0]=[r('<h1 id="rag-应用工程概述" tabindex="-1">RAG 应用工程概述 <a class="header-anchor" href="#rag-应用工程概述" aria-label="Permalink to &quot;RAG 应用工程概述&quot;">​</a></h1><p>RAG 是检索增强生成，用来让大模型基于企业知识、业务文档和外部资料回答问题。RAG 应用工程关注的不只是向量检索，而是从知识处理、召回、重排、上下文压缩、答案生成到引用溯源的完整链路。</p><h2 id="核心定位" tabindex="-1">核心定位 <a class="header-anchor" href="#核心定位" aria-label="Permalink to &quot;核心定位&quot;">​</a></h2><ul><li><strong>降低幻觉</strong>：让模型回答时依赖可追溯的知识来源。</li><li><strong>连接企业知识</strong>：把内部文档、制度、工单和业务数据接入 AI 应用。</li><li><strong>提升答案质量</strong>：通过检索、重排、压缩、引用和评测持续优化效果。</li></ul><h2 id="工程链路" tabindex="-1">工程链路 <a class="header-anchor" href="#工程链路" aria-label="Permalink to &quot;工程链路&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>说明</th></tr></thead><tbody><tr><td>知识处理</td><td>文档解析、切分、清洗、元数据标注和索引构建</td></tr><tr><td>检索召回</td><td>向量检索、关键词检索、混合检索和 Query 改写</td></tr><tr><td>答案生成</td><td>重排、上下文压缩、Prompt 拼装、答案合成和引用溯源</td></tr><tr><td>质量优化</td><td>相关性评估、幻觉控制、检索缓存和反馈闭环</td></tr></tbody></table><h2 id="学习路线" tabindex="-1">学习路线 <a class="header-anchor" href="#学习路线" aria-label="Permalink to &quot;学习路线&quot;">​</a></h2><ol><li>先理解 RAG 的工作流和适用边界，避免把所有问题都交给 RAG。</li><li>再掌握检索、重排、答案生成和引用溯源的核心实现。</li><li>最后学习 LangChain RAG 实战和高级 RAG 方案，形成可复用项目结构。</li></ol>',8)]))}const u=a(o,[["render",d]]);export{b as __pageData,u as default};
